// Agrupar por participante para evitar duplicatas
const participantes = {};

items.forEach(item => {
  const id = item.json.usuario_id;

  if (!participantes[id]) {
    participantes[id] = {
      usuario_id: id,
      participanteNome: item.json.participanteNome,
      unidadeSigla: item.json.unidadeSigla,
      tipoModalidadeNome: item.json.tipoModalidadeNome,
      meses_consecutivos: [],
      total_atrasos: 0
    };
  }

  participantes[id].meses_consecutivos.push({
    periodo_inicio: item.json.data_inicio_avaliativo,
    periodo_fim: item.json.data_fim_avaliativo,
    data_conclusao: item.json.dataConclusao,
    ptcId: item.json.ptcId
  });

  participantes[id].total_atrasos++;
});

// Converter para array
const resultado = Object.values(participantes).map(p => ({
  json: {
    ...p,
    quantidade_meses_consecutivos: p.meses_consecutivos.length,
    // Formatar períodos para exibição
    periodos_formatados: p.meses_consecutivos
      .map(m => `${m.periodo_inicio} a ${m.periodo_fim} (concluído em ${m.data_conclusao})`)
      .join('; '),
    // Flag para facilitar filtros
    requer_desligamento: p.meses_consecutivos.length >= 2
  }
}));

return resultado;

// Gerar relatório consolidado em formato CSV
const csv_header = "Usuario ID,Nome,Unidade,Modalidade,Meses Consecutivos,Total Atrasos,Períodos\n";

const csv_rows = items.map(item => {
  const j = item.json;
  return `"${j.usuario_id}","${j.participanteNome}","${j.unidadeSigla}","${j.tipoModalidadeNome}",${j.quantidade_meses_consecutivos},${j.total_atrasos},"${j.periodos_formatados}"`;
}).join("\n");

const csv_content = csv_header + csv_rows;

return [{
  json: {
    filename: `desligamentos_pgd_${new Date().toISOString().split('T')[0]}.csv`,
    content: csv_content,
    total_participantes: items.length,
    data_geracao: new Date().toISOString()
  }
}];
